import typesense
import json

client = typesense.Client({
    'nodes': [{
        'host': 'localhost',
        'port': '8108',
        'protocol': 'http'
    }],
    'api_key': 'xyz',
    'connection_timeout_seconds': 2
})

def search(keyword, color):
    # filter_by: orders.line_items.attributes.color:=color
    # Wait, is color case-sensitive? In typesense, string exact filtering is done with :=
    # Let's see what happens.
    search_parameters = {
        'q': keyword,
        'query_by': 'orders.line_items.name',
        'filter_by': f'orders.line_items.attributes.color:={color}',
        'facet_by': 'orders.line_items.category'
    }
    res = client.collections['nested_orders'].documents.search(search_parameters)

    # Extract matched customer IDs
    matched_ids = sorted([hit['document']['id'] for hit in res.get('hits', [])])

    # Extract facet counts
    facet_counts = {}
    for facet in res.get('facet_counts', []):
        if facet['field_name'] == 'orders.line_items.category':
            for count in facet['counts']:
                facet_counts[count['value']] = count['count']

    print(f"Keyword: {keyword}, Color: {color}")
    print(json.dumps({
        "matched_customer_ids": matched_ids,
        "category_facet_counts": facet_counts
    }))
    print("-" * 40)

search("Wireless", "black")
search("Wireless", "white")
search("Ceramic", "blue")
search("Steel", "silver")

